package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.deser.PropertyBasedCreator;
import com.fasterxml.jackson.databind.deser.SettableBeanProperty;
import com.fasterxml.jackson.databind.deser.impl.ext.ExtTypedProperty;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.TokenBuffer;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class ExternalTypeHandler_complete_TriageGen0Test {

    private JsonParser p;
    private DeserializationContext ctxt;
    private PropertyValueBuffer buffer;
    private PropertyBasedCreator creator;
    private JavaType beanType;

    @Before
    public void setUp() {
        p = mock(JsonParser.class);
        ctxt = mock(DeserializationContext.class);
        buffer = mock(PropertyValueBuffer.class);
        creator = mock(PropertyBasedCreator.class);
        beanType = mock(JavaType.class);
    }

    /**
     * Helper to instantiate the protected ExternalTypeHandler via reflection or builder
     * Since the constructor is protected and requires complex internal arrays, 
     * we simulate the internal state via reflection for testing purposes.
     */
    private ExternalTypeHandler createHandler(ExtTypedProperty[] properties, String[] typeIds, Object[] tokens) throws Exception {
        ExternalTypeHandler handler = ExternalTypeHandler.builder(beanType).build();

        setInternalField(handler, "_properties", properties);
        setInternalField(handler, "_typeIds", typeIds);
        setInternalField(handler, "_tokens", tokens);

        // Mock the _deserialize method behavior by overriding via a spy if possible, 
        // but since it's a real method in the class, we'll assume it's part of the logic.
        // For this test, we will use a spy to control _deserialize.
        return spy(handler);
    }

    private void setInternalField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testComplete_AllNormalProperties() throws Exception {
        SettableBeanProperty prop1 = mock(SettableBeanProperty.class);
        when(prop1.getCreatorIndex()).thenReturn(-1);

        ExtTypedProperty extProp1 = mock(ExtTypedProperty.class);
        when(extProp1.getProperty()).thenReturn(prop1);

        ExtTypedProperty[] properties = new ExtTypedProperty[]{extProp1};
        String[] typeIds = new String[]{"type1"};
        Object[] tokens = new Object[]{mock(com.fasterxml.jackson.core.io.TokenBuffer.class)};

        ExternalTypeHandler handler = createHandler(properties, typeIds, tokens);
        Object bean = new Object();
        when(creator.build(ctxt, buffer)).thenReturn(bean);
        doReturn("val1").when(handler)._deserialize(any(), any(), eq(0), eq("type1"));

        Object result = handler.complete(p, ctxt, buffer, creator);

        assertEquals(bean, result);
        verify(prop1).set(bean, "val1");
    }

    @Test
    public void testComplete_WithCreatorProperties() throws Exception {
        SettableBeanProperty prop1 = mock(SettableBeanProperty.class);
        when(prop1.getCreatorIndex()).thenReturn(0); // Creator property

        SettableBeanProperty typeProp = mock(SettableBeanProperty.class);
        when(typeProp.getCreatorIndex()).thenReturn(1); // Type property is also creator

        ExtTypedProperty extProp1 = mock(ExtTypedProperty.class);
        when(extProp1.getProperty()).thenReturn(prop1);
        when(extProp1.getTypeProperty()).thenReturn(typeProp);

        ExtTypedProperty[] properties = new ExtTypedProperty[]{extProp1};
        String[] typeIds = new String[]{"type1"};
        Object[] tokens = new Object[]{mock(com.fasterxml.jackson.core.io.TokenBuffer.class)};

        ExternalTypeHandler handler = createHandler(properties, typeIds, tokens);
        Object bean = new Object();
        when(creator.build(ctxt, buffer)).thenReturn(bean);
        doReturn("val1").when(handler)._deserialize(any(), any(), eq(0), eq("type1"));

        handler.complete(p, ctxt, buffer, creator);

        verify(buffer).assignParameter(prop1, "val1");
        verify(buffer).assignParameter(typeProp, "type1");
        verify(prop1, never()).set(any(), any()); // Creator props shouldn't be set via set()
    }

    @Test
    public void testComplete_MissingTypeId_WithDefaultType() throws Exception {
        SettableBeanProperty prop1 = mock(SettableBeanProperty.class);
        when(prop1.getCreatorIndex()).thenReturn(-1);

        ExtTypedProperty extProp1 = mock(ExtTypedProperty.class);
        when(extProp1.getProperty()).thenReturn(prop1);
        when(extProp1.hasDefaultType()).thenReturn(true);
        when(extProp1.getDefaultTypeId()).thenReturn("defaultType");

        ExtTypedProperty[] properties = new ExtTypedProperty[]{extProp1};
        String[] typeIds = new String[]{null};
        Object[] tokens = new Object[]{mock(com.fasterxml.jackson.core.io.TokenBuffer.class)};

        ExternalTypeHandler handler = createHandler(properties, typeIds, tokens);
        Object bean = new Object();
        when(creator.build(ctxt, buffer)).thenReturn(bean);
        doReturn("val1").when(handler)._deserialize(any(), any(), eq(0), eq("defaultType"));

        handler.complete(p, ctxt, buffer, creator);

        verify(prop1).set(bean, "val1");
    }

    @Test(expected = IOException.class)
    public void testComplete_MissingTypeId_NoDefaultType_ThrowsException() throws Exception {
        SettableBeanProperty prop1 = mock(SettableBeanProperty.class);
        ExtTypedProperty extProp1 = mock(ExtTypedProperty.class);
        when(extProp1.getProperty()).thenReturn(prop1);
        when(extProp1.hasDefaultType()).thenReturn(false);
        when(extProp1.getTypePropertyName()).thenReturn("typePropName");

        ExtTypedProperty[] properties = new ExtTypedProperty[]{extProp1};
        String[] typeIds = new String[]{null};
        Object[] tokens = new Object[]{mock(com.fasterxml.jackson.core.io.TokenBuffer.class)};

        ExternalTypeHandler handler = createHandler(properties, typeIds, tokens);
        doThrow(new IOException()).when(ctxt).reportInputMismatch(any(), anyString(), anyString());

        handler.complete(p, ctxt, buffer, creator);
    }

    @Test(expected = IOException.class)
    public void testComplete_MissingPropertyForTypeId_ThrowsException() throws Exception {
        SettableBeanProperty prop1 = mock(SettableBeanProperty.class);
        when(prop1.getName()).thenReturn("propName");

        ExtTypedProperty extProp1 = mock(ExtTypedProperty.class);
        when(extProp1.getProperty()).thenReturn(prop1);
        when(extProp1.getTypePropertyName()).thenReturn("typePropName");

        ExtTypedProperty[] properties = new ExtTypedProperty[]{extProp1};
        String[] typeIds = new String[]{"someId"};
        Object[] tokens = new Object[]{null}; // Token is null, but typeId is not

        ExternalTypeHandler handler = createHandler(properties, typeIds, tokens);
        doThrow(new IOException()).when(ctxt).reportInputMismatch(any(), anyString(), anyString());

        handler.complete(p, ctxt, buffer, creator);
    }

    @Test
    public void testComplete_BothNull_Skips() throws Exception {
        ExtTypedProperty extProp1 = mock(ExtTypedProperty.class);
        ExtTypedProperty[] properties = new ExtTypedProperty[]{extProp1};
        String[] typeIds = new String[]{null};
        Object[] tokens = new Object[]{null};

        ExternalTypeHandler handler = createHandler(properties, typeIds, tokens);
        Object bean = new Object();
        when(creator.build(ctxt, buffer)).thenReturn(bean);

        Object result = handler.complete(p, ctxt, buffer, creator);

        assertEquals(bean, result);
        verify(handler, never())._deserialize(any(), any(), anyInt(), anyString());
    }
}
